<script setup lang="ts">
import {useLocalPagination} from './localPagination'
import {useTableWidths as useListTableWidths} from './tableWidths'
const listWidths=useListTableWidths('UserPanelLists')

import {ref,reactive,onMounted,watch,computed} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import {api,session,can,firstAllowed} from './session'
import {useTableWidths} from './tableWidths'
const widths=useTableWidths('UserAccess')
const tab=ref(firstAllowed('users',['users','roles','mcp'])),users=ref<any[]>([]),roles=ref<any[]>([]),catalog=ref<any[]>([]),tokens=ref<any[]>([]),warehouses=ref<any[]>([]),stores=ref<string[]>([]),busy=ref(false),error=ref(''),dialog=ref(''),editing=ref<any>(null)
const form=reactive<any>({}),roleForm=reactive({name:'',description:'',permissions:[] as string[]}),tokenUser=ref<number>(session.value!.id),secret=ref(''),secretDialog=ref(false),newPassword=ref('')
const accountSearch=ref(''),userRole=ref(''),roleSearch=ref('')
const filteredUsers=computed(()=>users.value.filter(u=>u.username.toLowerCase().includes(accountSearch.value.trim().toLowerCase())&&(!userRole.value||(userRole.value==='admin'?u.is_admin:u.roles?.some((r:any)=>String(r.id)===userRole.value)))))
const filteredRoles=computed(()=>roles.value.filter(r=>r.name.toLowerCase().includes(roleSearch.value.trim().toLowerCase())))
const writable=computed(()=>can('users.'+tab.value,'operate'))
const matrixWritable=computed(()=>can('users.roles','operate'))
const date=(v:string)=>v?new Date(v).toLocaleString('zh-CN'):'—'
async function load(){busy.value=true;error.value='';try{
 if(tab.value==='users'){const d=await api('/users');users.value=d.users;stores.value=d.stores;warehouses.value=d.warehouses||[];roles.value=await api('/access/roles')}
 if(tab.value==='roles'){roles.value=await api('/access/roles');catalog.value=await api('/access/catalog')}
 if(tab.value==='mcp'){tokens.value=await api('/access/tokens');if(session.value?.is_admin){const d=await api('/users');users.value=d.users}}
 }catch(e){error.value=(e as Error).message}finally{busy.value=false}}
watch(tab,()=>{secret.value='';load()});onMounted(load)
function openUser(u?:any){editing.value=u||null;Object.assign(form,{username:u?.username||'',password:'',stores:[...(u?.stores||[])],default_store:u?.default_store||'',active:u?.active??true,warehouse_ids:[...(u?.warehouse_ids||[])],role_ids:(u?.roles||[]).map((r:any)=>r.id)});dialog.value='user'}
async function saveUser(){await run(async()=>{const b={...form};if(editing.value){delete b.username;delete b.password}await api(editing.value?`/users/${editing.value.id}/settings`:'/users',b);dialog.value='';await load();ElMessage.success('用户已保存')})}
async function run(fn:()=>Promise<void>){busy.value=true;try{await fn()}catch(e){ElMessage.error((e as Error).message)}finally{busy.value=false}}
function openRole(r?:any){editing.value=r||null;Object.assign(roleForm,{name:r?.name||'',description:r?.description||'',permissions:[...(r?.permissions||[])]});dialog.value='role'}
function toggle(key:string,action:string,value:any){const set=new Set(roleForm.permissions);const targets=[key,...(!key.includes('.')?catalog.value.filter(r=>r.parent===key).map(r=>r.key):[])];for(const k of targets){if(value){set.add(k+'.'+action);set.add(k+'.view');if(k.includes('.'))set.add(k.split('.')[0]+'.view')}else{set.delete(k+'.'+action);if(action==='view')set.delete(k+'.operate')}}roleForm.permissions=[...set]}
function columnSelection(action:string){const count=catalog.value.filter(r=>roleForm.permissions.includes(r.key+'.'+action)).length;return {all:catalog.value.length>0&&count===catalog.value.length,partial:count>0&&count<catalog.value.length}}
function toggleAll(action:string,value:any){for(const row of catalog.value)toggle(row.key,action,value)}
async function saveRole(){await run(async()=>{const id=editing.value?.id;await api('/access/roles'+(id?'/'+id:''),roleForm);dialog.value='';await load();ElMessage.success('角色权限已保存，立即生效')})}
async function removeRole(r:any){try{await ElMessageBox.confirm('删除角色“'+r.name+'”？已分配的角色需先解除分配。','删除角色');await run(async()=>{await api(`/access/roles/${r.id}/delete`,{});await load()})}catch{}}
function password(u:any){editing.value=u;newPassword.value='';dialog.value='password'}
async function savePassword(){await run(async()=>{await api(`/users/${editing.value.id}/password`,{password:newPassword.value});dialog.value='';newPassword.value='';ElMessage.success('密码已重置')})}
async function generate(){try{await ElMessageBox.confirm('生成新 Token 后，该用户的旧 Token 将立即失效。新 Token 有效期 90 天，仅显示一次。','生成个人 Token');await run(async()=>{const d=await api('/access/tokens',{user_id:tokenUser.value});secret.value=d.token;secretDialog.value=true;await load()})}catch{}}
async function revoke(row:any){try{await ElMessageBox.confirm('撤销后，使用此 Token 的调用将立即被拒绝。','撤销 Token');await run(async()=>{await api(`/access/tokens/${row.id}/revoke`,{});await load()})}catch{}}
async function copy(){try{await navigator.clipboard.writeText(secret.value);ElMessage.success('已复制')}catch{ElMessage.info('请选中 Token 手动复制')}}
const config=JSON.stringify({mcpServers:{'amazon-erp':{url:window.location.origin+'/mcp',headers:{Authorization:'Bearer <个人Token>'}}}},null,2)
const usersPager=useLocalPagination(()=>filteredUsers.value)
const rolesPager=useLocalPagination(()=>filteredRoles.value)
const tokensPager=useLocalPagination(()=>tokens.value)
</script>
<template><section class="panel access-panel"><el-radio-group v-model="tab"><el-radio-button v-for="(name,key) in {users:'用户管理',roles:'角色管理',mcp:'MCP'}" :key="key" :value="key" v-show="can('users.'+key)">{{name}}</el-radio-button></el-radio-group>
<div class="access-tools"><template v-if="tab==='users'"><el-input v-model="accountSearch" placeholder="搜索账号" clearable style="width:220px"/><el-select v-model="userRole" aria-label="用户角色筛选" placeholder="全部角色" clearable><el-option value="admin" label="系统管理员"/><el-option v-for="r in roles" :key="r.id" :value="String(r.id)" :label="r.name"/></el-select></template><el-input v-if="tab==='roles'" v-model="roleSearch" placeholder="搜索角色名称" clearable style="width:220px"/><el-button @click="load">刷新列表</el-button><el-button v-if="tab==='users'&&writable" type="primary" @click="openUser()">新增用户</el-button><el-button v-if="tab==='roles'&&writable" type="primary" @click="openRole()">新增角色</el-button><template v-if="tab==='mcp'"><el-select v-if="session?.is_admin" v-model="tokenUser" placeholder="选择用户"><el-option v-for="u in users" :key="u.id" :value="u.id" :label="u.username" :disabled="!u.active"/></el-select><el-button v-if="writable" type="primary" @click="generate">生成 / 重新生成个人 Token</el-button></template><TableReset :table-key="tab==='users'?'UserAccess/users':tab==='roles'?'UserPanelLists/list-1':'UserPanelLists/list-2'"/></div>
<el-alert v-if="error" :title="error" type="error" :closable="false"/>
<template v-if="tab==='users'"><el-table  :data="usersPager.rows.value" v-loading="busy" border data-width-key="UserAccess/users" @header-dragend="(w:number,_:number,c:any)=>widths.resize('users',w,c)"><el-table-column prop="username" column-key="username" label="账号" :width="widths.width('users','username',160)"/><el-table-column label="角色" min-width="220"><template #default="{row}"><el-tag v-if="row.is_admin">系统管理员</el-tag><el-tag v-for="r in row.roles" :key="r.id">{{r.name}}</el-tag><span v-if="!row.is_admin&&!row.roles?.length">未分配</span></template></el-table-column><el-table-column label="授权店铺" min-width="220"><template #default="{row}">{{row.stores.join('、')}}</template></el-table-column><el-table-column label="授权仓库" min-width="200"><template #default="{row}">{{row.is_admin?'全部仓库':warehouses.filter(w=>row.warehouse_ids?.includes(w.id)).map(w=>w.name).join('、')||'未授权'}}</template></el-table-column><el-table-column prop="default_store" label="默认店铺"/><el-table-column label="状态" width="100"><template #default="{row}">{{row.active?'启用':'停用'}}</template></el-table-column><el-table-column v-if="writable" label="操作" width="200" fixed="right"><template #default="{row}"><el-button link type="primary" :disabled="row.is_admin&&!session?.is_admin" @click="openUser(row)">编辑 / 赋予角色</el-button><el-button link :disabled="row.is_admin&&!session?.is_admin" @click="password(row)">重置密码</el-button></template></el-table-column></el-table><AppPagination v-model:current-page="usersPager.page.value" v-model:page-size="usersPager.pageSize.value" :total="usersPager.total.value"/></template>
<template v-if="tab==='roles'"><el-table data-width-key="UserPanelLists/list-1" @header-dragend="(w:number,_:number,c:any)=>listWidths.resize('list-1',w,c)" @header-contextmenu="(c:any,e:MouseEvent)=>listWidths.resetColumn('list-1',c,e)"  :data="rolesPager.rows.value" border><el-table-column :column-key="'name'" :width="listWidths.width('list-1','name',undefined)" prop="name" label="角色名称"/><el-table-column :column-key="'description'" :width="listWidths.width('list-1','description',undefined)" prop="description" label="说明"/><el-table-column :column-key="'users'" :width="listWidths.width('list-1','users','140')" prop="users" label="已分配用户数" align="center" /><el-table-column :column-key="'column-4'" :width="listWidths.width('list-1','column-4','200')" label="操作" ><template #default="{row}"><el-button link type="primary" @click="openRole(row)">{{writable?'编辑 / 赋予权限':'查看权限'}}</el-button><el-button v-if="writable" link type="danger" @click="removeRole(row)">删除</el-button></template></el-table-column></el-table><AppPagination v-model:current-page="rolesPager.page.value" v-model:page-size="rolesPager.pageSize.value" :total="rolesPager.total.value"/></template>

<template v-if="tab==='mcp'"><p class="muted">有效期 90 天，功能权限跟随角色，店铺和仓库范围跟随用户授权。库存查询仅返回授权仓库；生成新 Token 会撤销旧 Token。</p><template v-if="true"><el-table data-width-key="UserPanelLists/list-2" @header-dragend="(w:number,_:number,c:any)=>listWidths.resize('list-2',w,c)" @header-contextmenu="(c:any,e:MouseEvent)=>listWidths.resetColumn('list-2',c,e)" :data="tokensPager.rows.value" border><el-table-column :column-key="'username'" :width="listWidths.width('list-2','username',undefined)" prop="username" label="用户"/><el-table-column :column-key="'column-2'" :width="listWidths.width('list-2','column-2',undefined)" label="Token 标识"><template #default="{row}">{{row.prefix}}…</template></el-table-column><el-table-column :column-key="'status'" :width="listWidths.width('list-2','status','100')" prop="status" label="状态" /><el-table-column :column-key="'column-4'" :width="listWidths.width('list-2','column-4',undefined)" label="到期时间"><template #default="{row}">{{date(row.expires_at)}}</template></el-table-column><el-table-column :column-key="'column-5'" :width="listWidths.width('list-2','column-5',undefined)" label="最近使用"><template #default="{row}">{{date(row.last_used_at)}}</template></el-table-column><el-table-column :column-key="'column-6'" :width="listWidths.width('list-2','column-6','100')" v-if="writable" label="操作" ><template #default="{row}"><el-button link type="danger" :disabled="row.status==='已撤销'" @click="revoke(row)">撤销</el-button></template></el-table-column></el-table><AppPagination v-model:current-page="tokensPager.page.value" v-model:page-size="tokensPager.pageSize.value" :total="tokensPager.total.value"/></template><details><summary>MCP 连接示例与开放能力</summary><pre>{{config}}</pre><p>Listing 查询、基本信息预览与确认修改、货件查询、订单查询、库存查询。远程服务需配置 HTTPS 并将 /mcp 转发到 ERP。</p><p>外部 MCP 服务也可直接使用 Bearer Token 调用 ERP API；接口清单：/api/integration/capabilities。</p></details></template>
<el-dialog v-model="secretDialog" title="个人 Token（仅显示一次）" width="650px" :close-on-click-modal="false" @closed="secret='' "><p>请复制保存。关闭后无法再次查看，只能重新生成。</p><el-input :model-value="secret" readonly aria-label="个人 Token"/><template #footer><el-button @click="copy">复制 Token</el-button><el-button type="primary" @click="secretDialog=false">已保存，关闭</el-button></template></el-dialog>
<el-dialog :model-value="dialog==='user'" :title="editing?'编辑用户':'新增用户'" width="600px" @close="dialog=''"><el-form label-position="top"><el-form-item label="账号"><el-input v-model="form.username" :disabled="!!editing"/></el-form-item><el-form-item v-if="!editing" label="密码"><el-input v-model="form.password" type="password" show-password autocomplete="new-password"/></el-form-item><el-form-item label="角色"><el-select v-model="form.role_ids" multiple style="width:100%"><el-option v-for="r in roles" :key="r.id" :value="r.id" :label="r.name"/></el-select></el-form-item><el-form-item label="授权店铺"><el-select v-model="form.stores" multiple style="width:100%" @change="form.default_store=form.stores.includes(form.default_store)?form.default_store:form.stores[0]||''"><el-option v-for="s in stores" :key="s" :value="s"/></el-select></el-form-item><el-form-item label="授权仓库"><el-select v-model="form.warehouse_ids" multiple style="width:100%" :disabled="editing?.is_admin" placeholder="选择仓库；不选则没有仓库数据权限"><el-option v-for="w in warehouses" :key="w.id" :value="w.id" :label="w.name"/></el-select></el-form-item><el-form-item label="默认店铺"><el-select v-model="form.default_store"><el-option v-for="s in form.stores" :key="s" :value="s"/></el-select></el-form-item><el-form-item label="启用"><el-switch v-model="form.active" :disabled="editing?.is_admin"/></el-form-item></el-form><template #footer><el-button @click="dialog=''">取消</el-button><el-button type="primary" :loading="busy" @click="saveUser">保存</el-button></template></el-dialog>
<el-dialog :model-value="dialog==='password'" title="重置密码" width="440px" @close="dialog=''"><el-input v-model="newPassword" type="password" show-password placeholder="新密码，至少 6 位"/><template #footer><el-button type="primary" :loading="busy" @click="savePassword">保存</el-button></template></el-dialog>
<el-dialog :model-value="dialog==='role'" :title="editing?'角色权限':'新增角色'" width="850px" @close="dialog=''"><el-form label-position="top"><el-form-item label="角色名称"><el-input v-model="roleForm.name" :disabled="!writable" maxlength="80"/></el-form-item><el-form-item label="说明"><el-input v-model="roleForm.description" :disabled="!writable" maxlength="500"/></el-form-item></el-form><template v-if="true"><TableReset table-key="UserPanelLists/list-3"/><el-table data-width-key="UserPanelLists/list-3" @header-dragend="(w:number,_:number,c:any)=>listWidths.resize('list-3',w,c)" @header-contextmenu="(c:any,e:MouseEvent)=>listWidths.resetColumn('list-3',c,e)" :data="catalog" max-height="440" border><el-table-column :column-key="'menu'" :width="listWidths.width('list-3','menu',undefined)" prop="menu" label="菜单"/><el-table-column :column-key="'tab'" :width="listWidths.width('list-3','tab',undefined)" prop="tab" label="页面 / Tab"/><el-table-column :column-key="a" :width="listWidths.width('list-3',a,'130')" v-for="(label,a) in {view:'查看',operate:'操作'}" :key="a" :label="label" ><template #header><el-checkbox :aria-label="label+'全选'" :disabled="!writable||!catalog.length" :model-value="columnSelection(a).all" :indeterminate="columnSelection(a).partial" @change="toggleAll(a,$event)">{{label}}全选</el-checkbox></template><template #default="{row}"><el-checkbox :aria-label="row.menu+' '+row.tab+' '+label" :disabled="!writable" :model-value="roleForm.permissions.includes(row.key+'.'+a)" @change="toggle(row.key,a,$event)"/></template></el-table-column></el-table></template><template #footer><el-button @click="dialog=''">关闭</el-button><el-button v-if="writable" type="primary" :loading="busy" @click="saveRole">保存角色</el-button></template></el-dialog>
</section></template>
<style scoped>.access-panel{padding:16px}.access-tools{display:flex;gap:10px;align-items:center;margin:16px 0}.access-tools .el-select{width:220px}.el-tag{margin-right:6px}details{margin:20px 0}pre{background:#f4f8f6;padding:16px;overflow:auto}.el-pagination{margin-top:16px}</style>
